std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_);
    for (std::size_t c = 0; c < cols_; ++c) {
        std::vector<std::size_t> rows(rows_);
        std::iota(rows.begin(), rows.end(), std::size_t{0});
        std::vector<double> column(rows_);
        std::transform(rows.begin(), rows.end(), column.begin(),
                       [this, c](std::size_t r) { return at(r, c); });
        result[c] = std::accumulate(column.begin(), column.end(), 0.0);
    }
    return result;
}

